import os
from datetime import datetime
from collections import defaultdict

# Use already-fetched records and fs_token from prior steps
base_dir = '/home/susan/photographs/vacations'

# categorize per instruction: January of this year => Athens, April of this year => Seoul, others => Paris
current_year = datetime.now().year
cats = {'Athens': [], 'Seoul': [], 'Paris': []}
for p, month, created_at in records:
    y = int(created_at[:4]) if created_at else None
    m = int(created_at[5:7]) if created_at and len(created_at)>=7 else None
    if y == current_year and m == 1:
        cats['Athens'].append(p)
    elif y == current_year and m == 4:
        cats['Seoul'].append(p)
    else:
        cats['Paris'].append(p)

print('current_year', current_year)
for k in ['Athens','Seoul','Paris']:
    print(k, len(cats[k]))

# show destination directories paths
for k in cats:
    print('dest', k, os.path.join(base_dir, k))

# check existing destination files (non-recursive) to detect collisions
existing = {}
for k in cats:
    dest_dir = os.path.join(base_dir, k)
    if apis.file_system.directory_exists(directory_path=dest_dir, access_token=fs_token)['exists']:
        files = apis.file_system.show_directory(access_token=fs_token, directory_path=dest_dir, recursive=False, entry_type='files')
        existing[k] = set(files)
    else:
        existing[k] = set()
    print('existing', k, len(existing[k]))

# create destination directories if needed
for k in cats:
    dest_dir = os.path.join(base_dir, k)
    if not apis.file_system.directory_exists(directory_path=dest_dir, access_token=fs_token)['exists']:
        apis.file_system.create_directory(directory_path=dest_dir, access_token=fs_token, recursive=False)
        print('created', dest_dir)
    else:
        print('already exists', dest_dir)

# perform moves; ensure destination filenames preserved
move_results = defaultdict(list)
for k, paths in cats.items():
    dest_dir = os.path.join(base_dir, k)
    for src in paths:
        fname = os.path.basename(src)
        dst = os.path.join(dest_dir, fname)
        # collision check
        if dst in existing[k]:
            move_results['collisions'].append((src,dst))
            continue
        res = apis.file_system.move_file(source_file_path=src, destination_file_path=dst, access_token=fs_token)
        move_results[k].append(res.get('destination_file_path'))

print('move counts', {k: len(v) for k,v in move_results.items()})
if move_results.get('collisions'):
    print('collisions', len(move_results['collisions']), move_results['collisions'][:5])

